    def tightestWindow(self, s: str, k: int) -> str:
        best = ""
        for i in range(len(s)):
            for j in range(i + 1, len(s) + 1):
                sub = s[i:j]
                if sub.count("1") != k:
                    continue
                if not best or len(sub) < len(best) or (len(sub) == len(best) and sub < best):
                    best = sub
        return best

