function tightestWindow(s: string, k: number): string {
  const pos: number[] = [];
  for (let i = 0; i < s.length; i++) if (s[i] === "1") pos.push(i);
  let best = "";
  for (let i = 0; i + k - 1 < pos.length; i++) {
    const cand = s.slice(pos[i], pos[i + k - 1] + 1);
    if (best === "" || cand.length < best.length || (cand.length === best.length && cand < best)) best = cand;
  }
  return best;
}

